begin;

-- ---------- เพิ่มหมวดหมู่ ----------
insert into categories (branch_id, code, name_th, sort_order)
select '448937cf-58c5-4007-b57b-6a8bcf46c2fe', 'network_cabling', 'ระบบเครือข่ายและสายสัญญาณ (Network & Cabling)', 16
where not exists (
  select 1 from categories where branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and code = 'network_cabling'
);

-- ---------- เพิ่มคำถาม (33 ข้อ) ----------
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบสายสัญญาณแบบมีโครงสร้าง (Structured Cabling System) คืออะไร และมีข้อดีอย่างไรเมื่อเทียบกับการเดินสายแบบเฉพาะกิจ', 'เป็นระบบเดินสายสัญญาณที่ออกแบบตามมาตรฐานเป็นลำดับชั้นที่ชัดเจน ครอบคลุมตั้งแต่จุดเชื่อมต่อผู้ใช้งานไปจนถึงห้องอุปกรณ์กลาง มีข้อดีคือรองรับการเปลี่ยนแปลงอุปกรณ์หรือระบบในอนาคตได้ง่าย ไม่ต้องเดินสายใหม่ทั้งหมด และง่ายต่อการตรวจสอบบำรุงรักษาเนื่องจากมีมาตรฐานการติดฉลากและการจัดระเบียบที่ชัดเจน', 'ต่างจากการเดินสายแบบเฉพาะกิจที่เดินสายตรงจากอุปกรณ์แต่ละชิ้นไปยังปลายทางโดยไม่มีมาตรฐานร่วมกัน ซึ่งเมื่อระบบขยายใหญ่ขึ้นจะยุ่งเหยิงและยากต่อการจัดการอย่างมาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบสายสัญญาณแบบมีโครงสร้าง (Structured Cabling System) คืออะไร และมีข้อดีอย่างไรเมื่อเทียบกับการเดินสายแบบเฉพาะกิจ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'โครงสร้างของระบบสายสัญญาณแบบมีโครงสร้างแบ่งออกเป็นสายแนวนอน (Horizontal Cabling) และสายแกนหลัก (Backbone Cabling) แตกต่างกันอย่างไร', 'สายแนวนอนเชื่อมต่อจากจุดเชื่อมต่อผู้ใช้งาน (Work Area) ไปยังห้องกระจายสายชั้นนั้น (Telecommunication Room) ภายในระยะทางที่จำกัดตามมาตรฐาน ส่วนสายแกนหลักเชื่อมต่อระหว่างห้องกระจายสายชั้นต่างๆ หรือระหว่างอาคาร มักใช้สายที่มีความสามารถส่งข้อมูลสูงกว่าและระยะทางไกลกว่า เช่น เส้นใยแก้วนำแสง', 'การแบ่งโครงสร้างเป็นลำดับชั้นนี้ช่วยให้การออกแบบและบำรุงรักษาระบบทำได้อย่างเป็นระบบ และช่วยจำกัดผลกระทบเมื่อเกิดปัญหาในส่วนใดส่วนหนึ่งไม่ให้กระทบทั้งระบบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'โครงสร้างของระบบสายสัญญาณแบบมีโครงสร้างแบ่งออกเป็นสายแนวนอน (Horizontal Cabling) และสายแกนหลัก (Backbone Cabling) แตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'แบบจำลอง OSI (Open Systems Interconnection Model) มีวัตถุประสงค์อะไรในการอธิบายการสื่อสารเครือข่าย', 'เป็นแบบจำลองเชิงทฤษฎีที่แบ่งกระบวนการสื่อสารเครือข่ายออกเป็น 7 ชั้น (Layer) แต่ละชั้นมีหน้าที่เฉพาะที่ชัดเจน ตั้งแต่ชั้นกายภาพ (Physical Layer) ที่เกี่ยวข้องกับสัญญาณไฟฟ้าหรือแสงจริง ไปจนถึงชั้นแอปพลิเคชัน (Application Layer) ที่ผู้ใช้งานโต้ตอบด้วยโดยตรง ช่วยให้เข้าใจและออกแบบระบบสื่อสารที่ซับซ้อนได้อย่างเป็นระบบ', 'การแบ่งเป็นชั้นทำให้แต่ละส่วนของระบบสามารถพัฒนาและปรับปรุงแยกจากกันได้ โดยไม่ต้องกระทบชั้นอื่น ตราบใดที่ยังคงรักษาส่วนต่อประสาน (Interface) ระหว่างชั้นให้เป็นไปตามมาตรฐาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'แบบจำลอง OSI (Open Systems Interconnection Model) มีวัตถุประสงค์อะไรในการอธิบายการสื่อสารเครือข่าย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'มาตรฐานอีเทอร์เน็ต (Ethernet) มีบทบาทอย่างไรในระบบเครือข่ายท้องถิ่น (Local Area Network, LAN)', 'เป็นมาตรฐานการสื่อสารที่กำหนดวิธีการส่งข้อมูลผ่านสายสัญญาณในเครือข่ายท้องถิ่น ครอบคลุมทั้งข้อกำหนดทางกายภาพ เช่น ชนิดของสายและขั้วต่อ และข้อกำหนดของโปรโตคอลในการควบคุมการเข้าถึงตัวกลางร่วมกัน เป็นมาตรฐานที่ใช้กันอย่างแพร่หลายที่สุดสำหรับเครือข่ายแบบมีสายในปัจจุบัน', 'มาตรฐานอีเทอร์เน็ตมีการพัฒนาต่อเนื่องหลายรุ่นเพื่อรองรับความเร็วในการส่งข้อมูลที่สูงขึ้นเรื่อยๆ ซึ่งสัมพันธ์กับคุณภาพของสายสัญญาณที่ต้องใช้ในการรองรับความเร็วแต่ละระดับ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'มาตรฐานอีเทอร์เน็ต (Ethernet) มีบทบาทอย่างไรในระบบเครือข่ายท้องถิ่น (Local Area Network, LAN)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'สายสัญญาณประเภท Cat5e, Cat6 และ Cat6a มีความแตกต่างกันอย่างไรในด้านความสามารถรองรับความเร็วเครือข่าย', 'แต่ละประเภทมีข้อกำหนดทางเทคนิคของสายที่แตกต่างกัน ทำให้รองรับความเร็วและระยะทางในการส่งข้อมูลได้แตกต่างกัน โดยทั่วไปประเภทที่มีตัวเลขสูงกว่ามักมีคุณภาพและความสามารถในการต้านทานสัญญาณรบกวนที่ดีกว่า ทำให้รองรับความเร็วสูงกว่าได้ในระยะทางเท่ากัน หรือรองรับความเร็วเท่ากันได้ในระยะทางที่ไกลกว่า', 'การเลือกประเภทสายที่เหมาะสมต้องพิจารณาทั้งความต้องการความเร็วเครือข่ายปัจจุบันและอนาคต เนื่องจากการเปลี่ยนสายสัญญาณที่เดินฝังในอาคารแล้วมีต้นทุนสูงกว่าการเลือกใช้สายคุณภาพสูงกว่าตั้งแต่แรกมาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'สายสัญญาณประเภท Cat5e, Cat6 และ Cat6a มีความแตกต่างกันอย่างไรในด้านความสามารถรองรับความเร็วเครือข่าย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'แผงกระจายสาย (Patch Panel) มีหน้าที่อะไรในห้องกระจายสายสัญญาณ', 'ทำหน้าที่เป็นจุดเชื่อมต่อกลางระหว่างสายแนวนอนที่เดินมาจากจุดเชื่อมต่อผู้ใช้งานแต่ละจุด กับอุปกรณ์เครือข่ายที่ทำงานจริง เช่น สวิตช์เครือข่าย ช่วยให้สามารถจัดระเบียบการเชื่อมต่อได้อย่างเป็นระบบ และสามารถเปลี่ยนแปลงการเชื่อมต่อได้ง่ายผ่านสาย Patch Cord สั้นๆ โดยไม่ต้องยุ่งกับสายแนวนอนที่ฝังอยู่ในผนังหรือพื้น', 'การติดฉลากที่ชัดเจนบนแผงกระจายสายและการจัดเส้นทางสาย Patch Cord อย่างเป็นระเบียบ เป็นแนวปฏิบัติที่ดีที่ช่วยให้การบำรุงรักษาและแก้ไขปัญหาเครือข่ายทำได้สะดวกรวดเร็วในระยะยาว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'แผงกระจายสาย (Patch Panel) มีหน้าที่อะไรในห้องกระจายสายสัญญาณ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'สวิตช์เครือข่าย (Network Switch) และเราเตอร์ (Router) มีหน้าที่แตกต่างกันอย่างไรในระบบเครือข่าย', 'สวิตช์ทำหน้าที่เชื่อมต่ออุปกรณ์ต่างๆ ภายในเครือข่ายเดียวกัน โดยส่งข้อมูลไปยังอุปกรณ์ปลายทางที่ถูกต้องภายในเครือข่ายนั้นตามที่อยู่ทางกายภาพของอุปกรณ์ ส่วนเราเตอร์ทำหน้าที่เชื่อมต่อระหว่างเครือข่ายที่แตกต่างกัน โดยตัดสินใจเส้นทางการส่งข้อมูลระหว่างเครือข่ายตามที่อยู่เชิงตรรกะ เพื่อให้ข้อมูลเดินทางไปถึงเครือข่ายปลายทางที่ถูกต้อง', 'ในเครือข่ายทั่วไป มักมีทั้งสวิตช์ที่เชื่อมต่ออุปกรณ์ภายในสำนักงานหรือชั้นเดียวกัน และเราเตอร์ที่เชื่อมต่อเครือข่ายภายในองค์กรออกไปยังเครือข่ายอินเทอร์เน็ตภายนอกหรือเครือข่ายสาขาอื่น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'สวิตช์เครือข่าย (Network Switch) และเราเตอร์ (Router) มีหน้าที่แตกต่างกันอย่างไรในระบบเครือข่าย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ที่อยู่ไอพี (IP Address) มีความสำคัญอย่างไรในการสื่อสารบนเครือข่าย', 'เป็นหมายเลขเฉพาะที่ใช้ระบุตัวตนของอุปกรณ์แต่ละเครื่องบนเครือข่าย ทำหน้าที่คล้ายที่อยู่บ้านที่ช่วยให้ข้อมูลที่ส่งผ่านเครือข่ายสามารถเดินทางไปถึงอุปกรณ์ปลายทางที่ถูกต้องได้ ไม่ว่าเครือข่ายนั้นจะมีอุปกรณ์เชื่อมต่ออยู่จำนวนมากเพียงใด', 'ระบบที่อยู่ไอพีมีการพัฒนาจากรุ่น IPv4 ที่มีจำนวนที่อยู่จำกัด ไปสู่รุ่น IPv6 ที่มีจำนวนที่อยู่มากขึ้นมหาศาล เพื่อรองรับจำนวนอุปกรณ์ที่เชื่อมต่อเครือข่ายที่เพิ่มขึ้นอย่างรวดเร็วในปัจจุบัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ที่อยู่ไอพี (IP Address) มีความสำคัญอย่างไรในการสื่อสารบนเครือข่าย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครือข่ายท้องถิ่น (Local Area Network, LAN) และเครือข่ายบริเวณกว้าง (Wide Area Network, WAN) แตกต่างกันอย่างไร', 'LAN ครอบคลุมพื้นที่จำกัด เช่น ภายในอาคารหรือบริเวณเดียวกัน มักเป็นเจ้าของและบริหารจัดการโดยองค์กรเดียว ในขณะที่ WAN ครอบคลุมพื้นที่กว้างกว่ามาก เช่น ระหว่างเมืองหรือระหว่างประเทศ มักต้องอาศัยโครงสร้างพื้นฐานจากผู้ให้บริการโทรคมนาคมภายนอกในการเชื่อมโยงระยะไกล', 'องค์กรที่มีหลายสาขากระจายอยู่ในพื้นที่ต่างๆ มักมีเครือข่าย LAN แยกกันในแต่ละสาขา แล้วเชื่อมต่อเข้าด้วยกันผ่านเครือข่าย WAN เพื่อให้สามารถแลกเปลี่ยนข้อมูลระหว่างสาขาได้อย่างต่อเนื่อง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครือข่ายท้องถิ่น (Local Area Network, LAN) และเครือข่ายบริเวณกว้าง (Wide Area Network, WAN) แตกต่างกันอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เทคโนโลยี Power over Ethernet (PoE) มีประโยชน์อย่างไรในการติดตั้งอุปกรณ์เครือข่าย', 'PoE ช่วยให้สามารถส่งทั้งข้อมูลและพลังงานไฟฟ้าผ่านสายสัญญาณเครือข่ายเส้นเดียวกันไปยังอุปกรณ์ปลายทาง เช่น กล้องวงจรปิดหรือจุดกระจายสัญญาณไร้สาย โดยไม่ต้องเดินสายไฟฟ้าแยกต่างหากไปยังตำแหน่งติดตั้งอุปกรณ์นั้น ช่วยลดความซับซ้อนและต้นทุนการเดินสายไฟฟ้าเพิ่มเติม', 'ข้อจำกัดของ PoE คือปริมาณกำลังไฟฟ้าที่ส่งได้มีขีดจำกัดตามมาตรฐานแต่ละรุ่น และระยะทางการส่งไฟฟ้าถูกจำกัดตามความยาวสายสัญญาณเครือข่ายที่รองรับได้ตามมาตรฐาน จึงเหมาะกับอุปกรณ์ที่ใช้กำลังไฟฟ้าไม่สูงมากเท่านั้น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เทคโนโลยี Power over Ethernet (PoE) มีประโยชน์อย่างไรในการติดตั้งอุปกรณ์เครือข่าย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ห้องกระจายสายหลัก (Main Distribution Frame, MDF) และห้องกระจายสายย่อย (Intermediate Distribution Frame, IDF) มีบทบาทแตกต่างกันอย่างไรในอาคารขนาดใหญ่', 'MDF เป็นจุดศูนย์กลางหลักที่รวบรวมการเชื่อมต่อจากภายนอกอาคารและเป็นจุดเริ่มต้นของสายแกนหลักที่กระจายไปยัง IDF แต่ละชั้นหรือแต่ละโซนของอาคาร ส่วน IDF ทำหน้าที่เป็นจุดกระจายสายย่อยในแต่ละพื้นที่ ที่เชื่อมต่อสายแนวนอนไปยังจุดใช้งานผู้ใช้ในบริเวณนั้นโดยเฉพาะ', 'การจัดวางตำแหน่ง IDF ในแต่ละชั้นหรือโซนช่วยจำกัดความยาวของสายแนวนอนให้อยู่ในระยะที่มาตรฐานกำหนด และช่วยลดความยุ่งยากในการบริหารจัดการเมื่อเทียบกับการเดินสายทุกจุดกลับไปยัง MDF โดยตรงในอาคารขนาดใหญ่', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ห้องกระจายสายหลัก (Main Distribution Frame, MDF) และห้องกระจายสายย่อย (Intermediate Distribution Frame, IDF) มีบทบาทแตกต่างกันอย่างไรในอาคารขนาดใหญ่'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดห้องกระจายสายสัญญาณ (Telecommunication Room) จึงต้องมีการควบคุมอุณหภูมิและความชื้นที่เหมาะสม', 'เพราะอุปกรณ์เครือข่ายที่ติดตั้งอยู่ภายใน เช่น สวิตช์และเราเตอร์ มักผลิตความร้อนขณะทำงานและมีความไวต่ออุณหภูมิและความชื้นที่สูงเกินไป ซึ่งอาจทำให้อุปกรณ์ทำงานผิดพลาดหรือมีอายุการใช้งานสั้นลง การควบคุมสภาพแวดล้อมที่เหมาะสมช่วยรักษาความน่าเชื่อถือและอายุการใช้งานของอุปกรณ์เครือข่าย', 'ห้องกระจายสายสัญญาณขนาดใหญ่ที่มีอุปกรณ์จำนวนมากมักต้องการระบบปรับอากาศเฉพาะที่ทำงานตลอด 24 ชั่วโมง แยกจากระบบปรับอากาศทั่วไปของอาคาร เพื่อความมั่นใจในเสถียรภาพของสภาพแวดล้อมแม้ในช่วงเวลาที่ระบบปรับอากาศหลักของอาคารปิดทำงาน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดห้องกระจายสายสัญญาณ (Telecommunication Room) จึงต้องมีการควบคุมอุณหภูมิและความชื้นที่เหมาะสม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การต่อกราวด์และการประสานศักย์ไฟฟ้า (Grounding and Bonding) สำหรับระบบสายสัญญาณโทรคมนาคม มีความสำคัญอย่างไรที่แตกต่างจากระบบไฟฟ้ากำลังทั่วไป', 'นอกจากวัตถุประสงค์ด้านความปลอดภัยเหมือนระบบไฟฟ้ากำลังทั่วไปแล้ว การต่อกราวด์ที่เหมาะสมในระบบโทรคมนาคมยังช่วยลดสัญญาณรบกวนและกระแสไหลวนที่อาจรบกวนคุณภาพสัญญาณข้อมูล อุปกรณ์เครือข่ายและตู้ Rack ที่ติดตั้งจึงต้องต่อกราวด์ด้วยระบบเฉพาะที่ออกแบบมาเพื่อรักษาศักย์ไฟฟ้าอ้างอิงเดียวกันทั่วทั้งระบบสื่อสาร', 'มาตรฐานการต่อกราวด์สำหรับงานโทรคมนาคมมักกำหนดแนวทางเฉพาะ เช่น การใช้แถบกราวด์หลัก (Telecommunications Main Grounding Busbar) ที่เชื่อมโยงอุปกรณ์ทั้งหมดในระบบเข้าด้วยกันอย่างเป็นระบบ แยกจากแต่เชื่อมโยงกับระบบกราวด์หลักของอาคาร', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การต่อกราวด์และการประสานศักย์ไฟฟ้า (Grounding and Bonding) สำหรับระบบสายสัญญาณโทรคมนาคม มีความสำคัญอย่างไรที่แตกต่างจากระบบไฟฟ้ากำลังทั่วไป'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'การจัดการสายสัญญาณในตู้ Rack (Cable Management) มีความสำคัญอย่างไรต่อการบำรุงรักษาระยะยาว', 'การจัดสายที่เป็นระเบียบช่วยให้สามารถระบุและติดตามเส้นทางของสายแต่ละเส้นได้ง่าย ลดความเสี่ยงจากการดึงหรือถอดสายผิดเส้นขณะบำรุงรักษาซึ่งอาจทำให้ระบบอื่นหยุดทำงานโดยไม่ตั้งใจ อีกทั้งยังช่วยให้อากาศไหลเวียนระบายความร้อนของอุปกรณ์ในตู้ Rack ได้ดีขึ้นเมื่อไม่มีสายพันกันยุ่งเหยิงขวางทางระบายอากาศ', 'การใช้อุปกรณ์จัดสาย เช่น รางจัดสายหรือที่รัดสาย พร้อมการติดฉลากที่ชัดเจนตั้งแต่การติดตั้งครั้งแรก เป็นการลงทุนเวลาที่คุ้มค่าในระยะยาว เมื่อเทียบกับความยุ่งยากในการแก้ไขปัญหาในระบบที่สายพันกันไม่เป็นระเบียบ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'การจัดการสายสัญญาณในตู้ Rack (Cable Management) มีความสำคัญอย่างไรต่อการบำรุงรักษาระยะยาว'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เครื่องมือ TDR (Time Domain Reflectometer) ใช้ตรวจสอบสายสัญญาณเครือข่ายด้วยหลักการอย่างไร', 'ส่งพัลส์สัญญาณไฟฟ้าเข้าไปในสายที่ต้องการทดสอบ แล้ววัดเวลาและลักษณะของสัญญาณสะท้อนกลับที่เกิดขึ้นเมื่อพัลส์นั้นกระทบกับจุดที่มีความไม่ต่อเนื่องของอิมพีแดนซ์ เช่น จุดสายขาด จุดต่อที่ไม่สมบูรณ์ หรือปลายสาย นำมาคำนวณตำแหน่งของจุดผิดปกตินั้นตามความเร็วการเดินทางของสัญญาณในสาย', 'เครื่องมือนี้มีประโยชน์อย่างมากในการระบุตำแหน่งของปัญหาในสายสัญญาณที่ฝังอยู่ในผนังหรือพื้นโดยไม่ต้องรื้อเปิดโครงสร้างอาคารเพื่อค้นหาด้วยสายตา ช่วยประหยัดเวลาและค่าใช้จ่ายในการซ่อมบำรุงอย่างมาก', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เครื่องมือ TDR (Time Domain Reflectometer) ใช้ตรวจสอบสายสัญญาณเครือข่ายด้วยหลักการอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'สัญญาณรบกวนข้ามสาย (Crosstalk) ในสายสัญญาณเครือข่ายเกิดขึ้นได้อย่างไร และมีผลกระทบต่อคุณภาพสัญญาณอย่างไร', 'เกิดจากการเหนี่ยวนำสัญญาณไฟฟ้าระหว่างคู่สายที่อยู่ใกล้กันภายในสายเคเบิลเดียวกันหรือสายเคเบิลที่วางเรียงชิดกัน สัญญาณจากคู่สายหนึ่งอาจรบกวนสัญญาณของคู่สายข้างเคียง ทำให้เกิดความผิดเพี้ยนของสัญญาณข้อมูลและอาจนำไปสู่ความผิดพลาดในการรับส่งข้อมูล', 'การบิดเกลียวของคู่สายที่แตกต่างกันในแต่ละคู่ภายในสายเคเบิลเดียวกัน เป็นเทคนิคหนึ่งที่ช่วยลดปัญหา Crosstalk เนื่องจากรูปแบบการบิดเกลียวที่ต่างกันช่วยลดโอกาสที่สัญญาณจากคู่สายต่างๆ จะเหนี่ยวนำกันในลักษณะที่สอดคล้องกันตลอดความยาวสาย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'สัญญาณรบกวนข้ามสาย (Crosstalk) ในสายสัญญาณเครือข่ายเกิดขึ้นได้อย่างไร และมีผลกระทบต่อคุณภาพสัญญาณอย่างไร'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดความยาวสูงสุดของสายสัญญาณเครือข่ายแบบทองแดง (เช่น 100 เมตรสำหรับอีเทอร์เน็ตทั่วไป) จึงมีข้อจำกัดที่ชัดเจน', 'เพราะการลดทอนสัญญาณและปัญหาสัญญาณรบกวนต่างๆ สะสมมากขึ้นตามความยาวของสาย เมื่อสายยาวเกินระยะที่กำหนด สัญญาณที่ปลายทางอาจอ่อนหรือผิดเพี้ยนมากเกินกว่าที่อุปกรณ์รับจะสามารถถอดรหัสข้อมูลได้อย่างถูกต้องตามมาตรฐานความเร็วที่กำหนด', 'หากจำเป็นต้องเดินสายในระยะทางที่ไกลกว่าขีดจำกัดของสายทองแดง จำเป็นต้องใช้อุปกรณ์ขยายสัญญาณหรือเปลี่ยนไปใช้เส้นใยแก้วนำแสงที่มีระยะทางการส่งไกลกว่ามากแทน ตามที่ได้กล่าวถึงหลักการของเส้นใยแก้วนำแสงไปแล้วในหมวดก่อนหน้า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดความยาวสูงสุดของสายสัญญาณเครือข่ายแบบทองแดง (เช่น 100 เมตรสำหรับอีเทอร์เน็ตทั่วไป) จึงมีข้อจำกัดที่ชัดเจน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'ระบบเครือข่ายไร้สายเฉพาะที่ (Wireless LAN) ที่ติดตั้งภายในอาคาร ยังคงต้องอาศัยระบบสายสัญญาณแบบมีโครงสร้างหรือไม่ เพราะเหตุใด', 'ยังคงต้องอาศัยเป็นอย่างมาก เนื่องจากจุดกระจายสัญญาณไร้สาย (Access Point) แต่ละจุดจำเป็นต้องเชื่อมต่อกับเครือข่ายหลักผ่านสายสัญญาณเพื่อรับส่งข้อมูลไปยังส่วนอื่นของเครือข่ายและอินเทอร์เน็ต การสื่อสารไร้สายเพียงทำหน้าที่เชื่อมโยงจากอุปกรณ์ผู้ใช้งานไปยัง Access Point ในระยะสั้นเท่านั้น', 'การวางแผนตำแหน่งติดตั้ง Access Point จึงยังคงต้องพิจารณาเส้นทางเดินสายสัญญาณแบบมีโครงสร้างไปยังตำแหน่งนั้น เช่นเดียวกับการวางแผนสำหรับอุปกรณ์เครือข่ายแบบมีสายทั่วไป แม้ผู้ใช้งานปลายทางจะเชื่อมต่อแบบไร้สายก็ตาม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'ระบบเครือข่ายไร้สายเฉพาะที่ (Wireless LAN) ที่ติดตั้งภายในอาคาร ยังคงต้องอาศัยระบบสายสัญญาณแบบมีโครงสร้างหรือไม่ เพราะเหตุใด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบเครือข่ายในอาคารสมัยใหม่จึงมักแบ่งเครือข่ายออกเป็นเครือข่ายย่อยเสมือน (Virtual LAN, VLAN) แทนที่จะใช้เครือข่ายเดียวรวมกันทั้งหมด', 'การแบ่ง VLAN ช่วยแยกกลุ่มอุปกรณ์หรือผู้ใช้งานตามหน้าที่หรือระดับความปลอดภัยที่แตกต่างกัน แม้จะเชื่อมต่อผ่านโครงสร้างสายสัญญาณและสวิตช์ทางกายภาพเดียวกัน ช่วยจำกัดการแพร่กระจายของทราฟฟิกเครือข่ายที่ไม่จำเป็นและเพิ่มความปลอดภัยด้วยการแยกกลุ่มข้อมูลที่มีความอ่อนไหวต่างกันออกจากกันในเชิงตรรกะ', 'ตัวอย่างเช่น การแยก VLAN สำหรับระบบควบคุมอาคารออกจากเครือข่ายสำนักงานทั่วไป ช่วยเพิ่มความปลอดภัยและลดความเสี่ยงที่ปัญหาจากเครือข่ายหนึ่งจะส่งผลกระทบต่ออีกเครือข่ายหนึ่งโดยไม่จำเป็น', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบเครือข่ายในอาคารสมัยใหม่จึงมักแบ่งเครือข่ายออกเป็นเครือข่ายย่อยเสมือน (Virtual LAN, VLAN) แทนที่จะใช้เครือข่ายเดียวรวมกันทั้งหมด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเลือกใช้สายเคเบิลชนิด Plenum Rated จึงมีความจำเป็นสำหรับการเดินสายผ่านพื้นที่เหนือฝ้าเพดานที่ใช้เป็นทางเดินอากาศ (Air Plenum) ของระบบปรับอากาศ', 'เพราะพื้นที่เหนือฝ้าเพดานที่ใช้เป็นทางเดินอากาศของระบบปรับอากาศ หากเกิดเพลิงไหม้ ควันและก๊าซพิษจากฉนวนสายเคเบิลที่ไม่ได้ออกแบบมาเป็นพิเศษอาจแพร่กระจายไปทั่วอาคารอย่างรวดเร็วผ่านระบบท่อลม สายเคเบิลชนิด Plenum Rated ผลิตด้วยวัสดุฉนวนที่ปล่อยควันและสารพิษน้อยกว่ามากเมื่อเกิดเพลิงไหม้ ลดความเสี่ยงต่อชีวิตของผู้ใช้อาคารในกรณีฉุกเฉิน', 'หลายพื้นที่มีข้อกำหนดทางกฎหมายที่บังคับให้ต้องใช้สายเคเบิลชนิดนี้เมื่อเดินสายผ่านพื้นที่ Plenum โดยเฉพาะ แม้จะมีต้นทุนสูงกว่าสายเคเบิลทั่วไปพอสมควร แต่เป็นข้อกำหนดด้านความปลอดภัยที่ไม่ควรมองข้าม', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเลือกใช้สายเคเบิลชนิด Plenum Rated จึงมีความจำเป็นสำหรับการเดินสายผ่านพื้นที่เหนือฝ้าเพดานที่ใช้เป็นทางเดินอากาศ (Air Plenum) ของระบบปรับอากาศ'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเดินสายสัญญาณเครือข่ายจึงต้องรักษารัศมีการดัดโค้งขั้นต่ำ (Minimum Bend Radius) ตามที่ผู้ผลิตกำหนด', 'หากดัดสายโค้งแคบเกินไป อาจทำให้โครงสร้างภายในของสาย เช่น การบิดเกลียวของคู่สายทองแดงหรือแกนกลางของเส้นใยแก้วนำแสง เสียรูปหรือเสียหาย ส่งผลให้คุณสมบัติทางไฟฟ้าหรือทางแสงของสายเปลี่ยนแปลงไป ลดความสามารถในการส่งสัญญาณหรือเพิ่มการลดทอนสัญญาณมากกว่าที่ควรจะเป็น', 'ปัญหานี้อาจไม่แสดงอาการทันทีหลังการติดตั้ง แต่อาจทำให้ประสิทธิภาพของสายลดลงและก่อปัญหาที่ตรวจพบได้ยากในภายหลัง การให้ความสำคัญกับรัศมีการดัดโค้งที่เหมาะสมตั้งแต่ขั้นตอนติดตั้งจึงเป็นแนวปฏิบัติที่ดีที่ช่วยป้องกันปัญหาระยะยาว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเดินสายสัญญาณเครือข่ายจึงต้องรักษารัศมีการดัดโค้งขั้นต่ำ (Minimum Bend Radius) ตามที่ผู้ผลิตกำหนด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการออกแบบเครือข่ายสำหรับองค์กรขนาดใหญ่ จึงมักพิจารณาสถาปัตยกรรมเครือข่ายแบบลำดับชั้น (Hierarchical Network Design) แทนที่จะเชื่อมต่ออุปกรณ์ทั้งหมดแบบเรียบ (Flat Network)', 'สถาปัตยกรรมแบบลำดับชั้นแบ่งเครือข่ายออกเป็นชั้นต่างๆ เช่น ชั้นเข้าถึง (Access) ชั้นกระจาย (Distribution) และชั้นแกนหลัก (Core) ช่วยให้การบริหารจัดการ การขยายระบบ และการแก้ไขปัญหาทำได้เป็นระบบมากขึ้น อีกทั้งยังช่วยจำกัดผลกระทบของปัญหาให้อยู่ในขอบเขตที่จำกัด ไม่ลุกลามไปทั้งเครือข่ายเหมือนเครือข่ายแบบเรียบที่ทุกอุปกรณ์เชื่อมต่อกันโดยตรงหรือใกล้เคียงกันมาก', 'การออกแบบแบบลำดับชั้นยังช่วยให้สามารถวางแผนความจุและประสิทธิภาพของแต่ละชั้นให้เหมาะสมกับปริมาณทราฟฟิกที่คาดว่าจะไหลผ่านในแต่ละจุดของเครือข่ายได้อย่างมีประสิทธิภาพมากกว่า', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการออกแบบเครือข่ายสำหรับองค์กรขนาดใหญ่ จึงมักพิจารณาสถาปัตยกรรมเครือข่ายแบบลำดับชั้น (Hierarchical Network Design) แทนที่จะเชื่อมต่ออุปกรณ์ทั้งหมดแบบเรียบ (Flat Network)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการสำรองระบบเครือข่ายหลักด้วยเส้นทางคู่ขนาน (Redundant Links) จึงต้องพิจารณาโปรโตคอลป้องกันการวนซ้ำของข้อมูล (Loop Prevention Protocol) ควบคู่กันไปด้วย', 'เพราะการเชื่อมต่อสวิตช์หลายตัวด้วยเส้นทางคู่ขนานโดยไม่มีการควบคุม อาจสร้างวงวนของเส้นทางข้อมูล (Network Loop) ที่ทำให้ข้อมูลเดินทางวนซ้ำไม่รู้จบภายในเครือข่าย ซึ่งจะทำให้เครือข่ายทั้งหมดล่มจากปริมาณทราฟฟิกที่ทวีคูณขึ้นอย่างรวดเร็ว โปรโตคอลป้องกันการวนซ้ำจึงจำเป็นเพื่อให้เครือข่ายสามารถมีเส้นทางสำรองได้อย่างปลอดภัยโดยไม่เกิดปัญหาวงวน', 'โปรโตคอลเหล่านี้ทำงานโดยตรวจจับและปิดกั้นเส้นทางที่ซ้ำซ้อนไว้ชั่วคราวในสภาวะปกติ แล้วเปิดใช้งานเส้นทางสำรองโดยอัตโนมัติเฉพาะเมื่อเส้นทางหลักเกิดความผิดปกติเท่านั้น เพื่อให้ได้ทั้งประโยชน์ของความซ้ำซ้อนและความปลอดภัยจากปัญหาวงวนไปพร้อมกัน', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการสำรองระบบเครือข่ายหลักด้วยเส้นทางคู่ขนาน (Redundant Links) จึงต้องพิจารณาโปรโตคอลป้องกันการวนซ้ำของข้อมูล (Loop Prevention Protocol) ควบคู่กันไปด้วย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวางแผนเครือข่ายสำหรับอาคารอัจฉริยะ (Smart Building) จึงต้องพิจารณาการเชื่อมโยงระบบต่างๆ เช่น ระบบควบคุมอาคาร ระบบรักษาความปลอดภัย และระบบเครือข่ายข้อมูลทั่วไป เข้าด้วยกันอย่างมีการวางแผน', 'เพราะอาคารอัจฉริยะสมัยใหม่มักใช้โครงสร้างพื้นฐานเครือข่ายเดียวกันหรือเชื่อมโยงกันสำหรับหลายระบบ เพื่อประหยัดต้นทุนโครงสร้างพื้นฐานและเพิ่มความสามารถในการวิเคราะห์ข้อมูลร่วมกันระหว่างระบบต่างๆ แต่การรวมระบบเข้าด้วยกันโดยไม่มีการวางแผนที่ดีด้านความปลอดภัยและการแบ่งแยกเครือข่าย อาจสร้างความเสี่ยงที่ปัญหาจากระบบหนึ่งจะส่งผลกระทบต่อระบบอื่นที่สำคัญกว่าได้', 'การใช้เทคนิค เช่น การแบ่ง VLAN หรือไฟร์วอลล์ภายในเพื่อแยกเครือข่ายของแต่ละระบบย่อยออกจากกันในเชิงตรรกะ ในขณะที่ยังคงใช้โครงสร้างพื้นฐานทางกายภาพร่วมกัน เป็นแนวทางที่นิยมใช้เพื่อสมดุลระหว่างประสิทธิภาพต้นทุนและความปลอดภัย', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวางแผนเครือข่ายสำหรับอาคารอัจฉริยะ (Smart Building) จึงต้องพิจารณาการเชื่อมโยงระบบต่างๆ เช่น ระบบควบคุมอาคาร ระบบรักษาความปลอดภัย และระบบเครือข่ายข้อมูลทั่วไป เข้าด้วยกันอย่างมีการวางแผน'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการทดสอบและตรวจสอบระบบสายสัญญาณเครือข่ายเป็นระยะ (Periodic Testing) จึงยังคงมีความจำเป็น แม้ระบบจะผ่านการทดสอบรับรองตั้งแต่ติดตั้งครั้งแรกแล้วก็ตาม', 'เพราะสภาพของสายสัญญาณและจุดเชื่อมต่ออาจเปลี่ยนแปลงไปตามเวลาจากปัจจัยต่างๆ เช่น การสั่นสะเทือน ความชื้น หรือการรบกวนทางกายภาพจากการปรับปรุงพื้นที่ในภายหลัง ซึ่งอาจทำให้คุณภาพสัญญาณลดลงจากที่เคยผ่านการทดสอบไว้ตอนแรก', 'การตรวจสอบเป็นระยะช่วยตรวจพบปัญหาที่ค่อยๆ พัฒนาขึ้นก่อนที่จะส่งผลกระทบร้ายแรงต่อการใช้งานจริง โดยเฉพาะในระบบที่มีความสำคัญสูงต่อการดำเนินงานขององค์กร ซึ่งการหยุดชะงักของเครือข่ายอาจก่อให้เกิดความเสียหายทางธุรกิจที่มีมูลค่าสูง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการทดสอบและตรวจสอบระบบสายสัญญาณเครือข่ายเป็นระยะ (Periodic Testing) จึงยังคงมีความจำเป็น แม้ระบบจะผ่านการทดสอบรับรองตั้งแต่ติดตั้งครั้งแรกแล้วก็ตาม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบเครือข่ายสำหรับศูนย์ข้อมูล (Data Center) จึงมักใช้สถาปัตยกรรมแบบ Spine-Leaf แทนสถาปัตยกรรมแบบลำดับชั้นดั้งเดิม', 'สถาปัตยกรรมแบบ Spine-Leaf ออกแบบให้ทุกสวิตช์ชั้น Leaf เชื่อมต่อกับทุกสวิตช์ชั้น Spine โดยตรง ทำให้เส้นทางการเดินทางของข้อมูลระหว่างจุดใดๆ ในเครือข่ายมีจำนวนขั้นตอนที่คงที่และคาดการณ์ได้ ต่างจากสถาปัตยกรรมแบบลำดับชั้นดั้งเดิมที่การสื่อสารระหว่างอุปกรณ์ในคนละสาขาของโครงสร้างต้องเดินทางผ่านหลายชั้นซึ่งอาจสร้างคอขวด (Bottleneck) ได้', 'สถาปัตยกรรมนี้เหมาะสมเป็นพิเศษกับศูนย์ข้อมูลสมัยใหม่ที่มีปริมาณทราฟฟิกระหว่างเซิร์ฟเวอร์ (East-West Traffic) สูงมาก ซึ่งแตกต่างจากรูปแบบทราฟฟิกดั้งเดิมที่ส่วนใหญ่เป็นการสื่อสารระหว่างผู้ใช้งานกับเซิร์ฟเวอร์ (North-South Traffic) เพียงอย่างเดียว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบเครือข่ายสำหรับศูนย์ข้อมูล (Data Center) จึงมักใช้สถาปัตยกรรมแบบ Spine-Leaf แทนสถาปัตยกรรมแบบลำดับชั้นดั้งเดิม'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการติดตั้งระบบเครือข่ายในโรงงานอุตสาหกรรมจึงต้องพิจารณาแยกเครือข่ายสำหรับระบบควบคุมกระบวนการ (Operational Technology, OT) ออกจากเครือข่ายข้อมูลสำนักงานทั่วไป (Information Technology, IT)', 'เพราะเครือข่าย OT มักมีความต้องการด้านความน่าเชื่อถือ ความหน่วงเวลาต่ำ และความปลอดภัยที่แตกต่างจากเครือข่าย IT ทั่วไป การรวมสองเครือข่ายเข้าด้วยกันโดยไม่มีการแบ่งแยกที่เหมาะสม อาจทำให้ปัญหาด้านความปลอดภัยไซเบอร์จากเครือข่าย IT ที่มักเปิดเชื่อมต่อกับอินเทอร์เน็ตภายนอกมากกว่า ส่งผลกระทบต่อระบบควบคุมกระบวนการที่สำคัญได้', 'แนวทางปฏิบัติที่ดีมักแนะนำให้มีการแบ่งเขตเครือข่าย (Network Segmentation) ที่ชัดเจนระหว่าง OT และ IT พร้อมจุดควบคุมการเชื่อมต่อระหว่างสองเครือข่ายที่มีการตรวจสอบอย่างเข้มงวด แทนที่จะเชื่อมต่อกันโดยตรงอย่างอิสระ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการติดตั้งระบบเครือข่ายในโรงงานอุตสาหกรรมจึงต้องพิจารณาแยกเครือข่ายสำหรับระบบควบคุมกระบวนการ (Operational Technology, OT) ออกจากเครือข่ายข้อมูลสำนักงานทั่วไป (Information Technology, IT)'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการวางแผนความจุของระบบเครือข่าย (Network Capacity Planning) จึงต้องพิจารณาทั้งปริมาณทราฟฟิกเฉลี่ยและปริมาณทราฟฟิกสูงสุด (Peak Traffic) แทนที่จะพิจารณาเพียงค่าเฉลี่ยเพียงอย่างเดียว', 'เพราะหากออกแบบระบบให้รองรับได้เพียงปริมาณทราฟฟิกเฉลี่ย ระบบอาจไม่สามารถรองรับได้ในช่วงเวลาที่มีการใช้งานสูงสุด เช่น ช่วงเวลาที่พนักงานทุกคนเริ่มงานพร้อมกันในตอนเช้า ทำให้เกิดความล่าช้าหรือการสูญเสียแพ็กเก็ตข้อมูลในช่วงเวลาสำคัญเหล่านั้น แม้ค่าเฉลี่ยตลอดวันจะดูเพียงพอก็ตาม', 'การวางแผนความจุที่ดีจึงต้องเก็บข้อมูลรูปแบบการใช้งานจริงในช่วงเวลาต่างๆ เพื่อระบุรูปแบบทราฟฟิกสูงสุดที่แท้จริง แล้วออกแบบระบบให้มีความจุเพียงพอรองรับสถานการณ์นั้นได้อย่างมีประสิทธิภาพ โดยไม่ต้องลงทุนเกินความจำเป็นสำหรับความจุที่ใช้เพียงบางช่วงเวลาสั้นๆ', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการวางแผนความจุของระบบเครือข่าย (Network Capacity Planning) จึงต้องพิจารณาทั้งปริมาณทราฟฟิกเฉลี่ยและปริมาณทราฟฟิกสูงสุด (Peak Traffic) แทนที่จะพิจารณาเพียงค่าเฉลี่ยเพียงอย่างเดียว'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการเอกสารบันทึกระบบเครือข่าย (Network Documentation) เช่น แผนผังการเชื่อมต่อและการกำหนดที่อยู่ไอพี จึงมีความสำคัญต่อการบริหารจัดการระบบในระยะยาว', 'เพราะเมื่อระบบเครือข่ายมีขนาดใหญ่และซับซ้อนขึ้น การขาดเอกสารที่ชัดเจนจะทำให้ผู้ดูแลระบบใหม่หรือผู้ที่ต้องแก้ไขปัญหาเร่งด่วนต้องเสียเวลาอย่างมากในการทำความเข้าใจโครงสร้างของระบบ ซึ่งอาจนำไปสู่ความล่าช้าในการแก้ไขปัญหาหรือความผิดพลาดจากการเข้าใจระบบไม่ถูกต้อง', 'การรักษาเอกสารให้เป็นปัจจุบันอยู่เสมอ (ไม่ใช่เพียงจัดทำครั้งเดียวตอนติดตั้ง) เป็นความท้าทายที่องค์กรจำนวนมากมองข้าม แต่มีความสำคัญอย่างยิ่งต่อประสิทธิภาพการบริหารจัดการเครือข่ายในระยะยาว โดยเฉพาะเมื่อบุคลากรที่เกี่ยวข้องเปลี่ยนแปลงไปตามเวลา', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการเอกสารบันทึกระบบเครือข่าย (Network Documentation) เช่น แผนผังการเชื่อมต่อและการกำหนดที่อยู่ไอพี จึงมีความสำคัญต่อการบริหารจัดการระบบในระยะยาว'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการออกแบบระบบเครือข่ายที่ดีจึงควรพิจารณาความสามารถในการขยายระบบ (Scalability) ตั้งแต่ขั้นตอนการวางแผนเบื้องต้น', 'เพราะความต้องการด้านเครือข่ายขององค์กรมักเติบโตขึ้นตามเวลา ทั้งจากจำนวนผู้ใช้งานที่เพิ่มขึ้นและปริมาณข้อมูลที่ต้องรับส่งที่มากขึ้น หากออกแบบระบบโดยไม่คำนึงถึงความสามารถในการขยายตั้งแต่แรก อาจต้องรื้อปรับโครงสร้างทั้งหมดในภายหลังซึ่งมีต้นทุนและความยุ่งยากสูงกว่าการวางแผนเผื่อไว้ตั้งแต่ต้นมาก', 'การออกแบบที่คำนึงถึง Scalability อาจรวมถึงการเลือกอุปกรณ์ที่สามารถเพิ่มขยายพอร์ตหรือความจุได้ การวางโครงสร้างเครือข่ายแบบลำดับชั้นที่รองรับการเพิ่มสาขาย่อยได้ง่าย และการเผื่อพื้นที่ทางกายภาพสำหรับอุปกรณ์เพิ่มเติมในอนาคต', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการออกแบบระบบเครือข่ายที่ดีจึงควรพิจารณาความสามารถในการขยายระบบ (Scalability) ตั้งแต่ขั้นตอนการวางแผนเบื้องต้น'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดในการโยกย้ายหรือปรับปรุงระบบเครือข่ายขนาดใหญ่ จึงควรมีการวางแผนช่วงเวลาดำเนินการ (Maintenance Window) และแผนสำรองในกรณีที่เกิดปัญหา (Rollback Plan) อย่างละเอียด', 'เพราะการเปลี่ยนแปลงระบบเครือข่ายขนาดใหญ่มีความเสี่ยงที่จะเกิดปัญหาที่ไม่คาดคิด ซึ่งอาจส่งผลกระทบต่อการดำเนินธุรกิจอย่างกว้างขวางหากเกิดขึ้นในช่วงเวลาทำการปกติ การกำหนดช่วงเวลาดำเนินการที่มีผลกระทบต่ำ พร้อมแผนสำรองที่ชัดเจนสำหรับการย้อนกลับสู่สภาพเดิมอย่างรวดเร็วหากพบปัญหา ช่วยลดความเสี่ยงและผลกระทบต่อองค์กรให้น้อยที่สุด', 'แผนสำรองที่ดีควรมีการทดสอบและเตรียมความพร้อมไว้ล่วงหน้า ไม่ใช่เพียงแนวคิดบนกระดาษ เพื่อให้สามารถดำเนินการย้อนกลับได้อย่างรวดเร็วจริงหากจำเป็น แทนที่จะต้องคิดหาวิธีแก้ไขปัญหาเฉพาะหน้าท่ามกลางความกดดันเมื่อเกิดปัญหาขึ้นจริง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดในการโยกย้ายหรือปรับปรุงระบบเครือข่ายขนาดใหญ่ จึงควรมีการวางแผนช่วงเวลาดำเนินการ (Maintenance Window) และแผนสำรองในกรณีที่เกิดปัญหา (Rollback Plan) อย่างละเอียด'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดวิศวกรออกแบบระบบเครือข่ายจึงควรพิจารณาผลกระทบของความหนาแน่นของอุปกรณ์เชื่อมต่อ (Device Density) ที่เพิ่มขึ้นอย่างต่อเนื่องจากแนวโน้ม IoT (Internet of Things) ในการวางแผนโครงสร้างพื้นฐานเครือข่าย', 'เพราะแนวโน้มการเชื่อมต่ออุปกรณ์ IoT จำนวนมาก เช่น เซนเซอร์ตรวจจับสภาพแวดล้อมหรืออุปกรณ์อัตโนมัติต่างๆ ในอาคารและโรงงาน ทำให้จำนวนอุปกรณ์ที่ต้องเชื่อมต่อเครือข่ายเพิ่มขึ้นอย่างมากเมื่อเทียบกับอดีตที่มีเพียงคอมพิวเตอร์และอุปกรณ์สำนักงานทั่วไป ซึ่งส่งผลต่อความต้องการด้านจำนวนที่อยู่ไอพี ความจุของสวิตช์ และปริมาณทราฟฟิกโดยรวมของเครือข่าย', 'การวางแผนโครงสร้างพื้นฐานเครือข่ายสมัยใหม่จึงต้องเผื่อรองรับความหนาแน่นของอุปกรณ์ที่สูงขึ้นมาก รวมถึงพิจารณาเทคโนโลยีเฉพาะสำหรับ IoT เช่น เครือข่ายพลังงานต่ำระยะไกล (Low Power Wide Area Network) ที่อาจเหมาะสมกว่าเครือข่ายอีเทอร์เน็ตทั่วไปสำหรับอุปกรณ์เซนเซอร์จำนวนมากที่ส่งข้อมูลปริมาณน้อยแต่บ่อยครั้ง', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดวิศวกรออกแบบระบบเครือข่ายจึงควรพิจารณาผลกระทบของความหนาแน่นของอุปกรณ์เชื่อมต่อ (Device Density) ที่เพิ่มขึ้นอย่างต่อเนื่องจากแนวโน้ม IoT (Internet of Things) ในการวางแผนโครงสร้างพื้นฐานเครือข่าย'
  );
insert into questions (category_id, question, answer, explanation, is_active, needs_review)
select c.id, 'เหตุใดการบูรณาการความรู้ด้านโครงสร้างพื้นฐานเครือข่ายเข้ากับการออกแบบอาคารตั้งแต่ขั้นตอนสถาปัตยกรรม จึงมีความสำคัญมากขึ้นเรื่อยๆ ในปัจจุบัน', 'เพราะระบบเครือข่ายไม่ได้เป็นเพียงส่วนเสริมของอาคารอีกต่อไป แต่กลายเป็นโครงสร้างพื้นฐานสำคัญที่จำเป็นสำหรับการทำงานของระบบอื่นๆ เกือบทั้งหมดในอาคารสมัยใหม่ ตั้งแต่ระบบควบคุมอาคาร ระบบรักษาความปลอดภัย ไปจนถึงการทำงานประจำวันของผู้ใช้อาคาร การพิจารณาความต้องการด้านเครือข่ายตั้งแต่ขั้นตอนออกแบบสถาปัตยกรรม ช่วยให้สามารถจัดสรรพื้นที่และเส้นทางเดินสายที่เหมาะสมได้อย่างมีประสิทธิภาพ แทนที่จะต้องดัดแปลงภายหลังซึ่งมีข้อจำกัดมากกว่า', 'แนวโน้มนี้สะท้อนให้เห็นถึงความสำคัญที่เพิ่มขึ้นของวิศวกรไฟฟ้าสื่อสารในทีมออกแบบอาคารสมัยใหม่ ซึ่งต้องทำงานประสานงานอย่างใกล้ชิดกับสถาปนิกและวิศวกรสาขาอื่นตั้งแต่ขั้นตอนแรกของการออกแบบ ไม่ใช่เข้ามาเกี่ยวข้องเพียงในขั้นตอนหลังที่โครงสร้างอาคารถูกกำหนดไว้แล้ว', true, true
from categories c
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
  and not exists (
    select 1 from questions q2
    where q2.category_id = c.id and q2.question = 'เหตุใดการบูรณาการความรู้ด้านโครงสร้างพื้นฐานเครือข่ายเข้ากับการออกแบบอาคารตั้งแต่ขั้นตอนสถาปัตยกรรม จึงมีความสำคัญมากขึ้นเรื่อยๆ ในปัจจุบัน'
  );

commit;

-- ---------- ตรวจสอบผลลัพธ์ ----------
select c.name_th as category, count(q.id) as question_count
from categories c
left join questions q on q.category_id = c.id
where c.branch_id = '448937cf-58c5-4007-b57b-6a8bcf46c2fe' and c.code = 'network_cabling'
group by c.name_th;
